-- Seeds the "industry_keyword_groups" company setting with the taxonomy that
-- used to be hardcoded in lib/constants.ts (INDUSTRY_KEYWORD_CATEGORIES),
-- so the Apollo import dropdown's cutover to Supabase-backed data is a no-op
-- for every existing company. From here it's editable per-company from
-- Settings > Industry Segments (components/app/settings-view.tsx) and via
-- the "add keyword to an existing group" flow in the import dropdown itself
-- (components/app/lead-forms.tsx) — both go through the existing
-- PATCH /api/v1/settings route, same as product_offerings.
insert into public.settings (company_id, key, value)
select id, 'industry_keyword_groups', $json$[{"id":"film","label":"Film Extrusion (client's priority list)","emoji":"🎞️","keywords":[{"id":"film-stretch-cling-film","label":"Stretch & Cling Film","query":"stretch film","starred":true},{"id":"film-shrink-film","label":"Shrink Film","query":"shrink film","starred":true},{"id":"film-plastic-film-general","label":"Plastic Film (general)","query":"plastic film","starred":true},{"id":"film-film-extrusion","label":"Film Extrusion","query":"film extrusion","starred":true},{"id":"film-blown-film","label":"Blown Film","query":"blown film","starred":true},{"id":"film-packaging-film","label":"Packaging Film","query":"packaging film"},{"id":"film-polyethylene-pe-film","label":"Polyethylene (PE) Film","query":"polyethylene film"},{"id":"film-cast-film","label":"Cast Film","query":"cast film"}]},{"id":"pet-bottles","label":"PET Bottles & Closures","emoji":"🧴","keywords":[{"id":"pet-bottles-beverage-bottles","label":"Beverage Bottles (Water/Juice/CSD)","query":"pet bottles","starred":true},{"id":"pet-bottles-pet-preforms","label":"PET Preforms","query":"pet preform"},{"id":"pet-bottles-cosmetic-personal-care-bottles","label":"Cosmetic & Personal Care Bottles","query":"cosmetic packaging","starred":true},{"id":"pet-bottles-pharma-agrochemical-bottles","label":"Pharma & Agrochemical Bottles","query":"pharmaceutical packaging"},{"id":"pet-bottles-caps-closures","label":"Caps & Closures","query":"caps and closures"}]},{"id":"blown-film","label":"Flexible Packaging","emoji":"📦","keywords":[{"id":"blown-film-packaging-films","label":"Packaging Films (Pouches/Lamination)","query":"flexible packaging","starred":true},{"id":"blown-film-milk-pouch-food-films","label":"Milk Pouch & Food Films","query":"blown film"},{"id":"blown-film-agricultural-films","label":"Agricultural Films (Mulch/Silage/Greenhouse)","query":"agricultural film"},{"id":"blown-film-courier-bags-industrial-bags","label":"Courier Bags & Industrial Bags","query":"plastic bags"}]},{"id":"blow-molding","label":"Blow Molding","emoji":"🪣","keywords":[{"id":"blow-molding-industrial-drums-ibcs","label":"Industrial Drums & IBCs","query":"industrial packaging"},{"id":"blow-molding-water-tanks-storage","label":"Water Tanks & Storage","query":"rotomoulding"},{"id":"blow-molding-automotive-blow-molded-parts","label":"Automotive Blow Molded Parts","query":"automotive components"}]},{"id":"injection-molding","label":"Injection & Roto Molding","emoji":"🔧","keywords":[{"id":"injection-molding-injection-molding-general","label":"Injection Molding (general)","query":"injection molding","starred":true},{"id":"injection-molding-thermoforming","label":"Thermoforming","query":"thermoforming"},{"id":"injection-molding-industrial-parts","label":"Industrial Parts (Crates/Pallets)","query":"plastic pallets"}]},{"id":"compounders","label":"Compounders","emoji":"⚗️","keywords":[{"id":"compounders-pe-pp-commodity-compounders","label":"PE/PP Commodity Compounders (PE100)","query":"polymers","starred":true},{"id":"compounders-engineering-plastic-compounders","label":"Engineering Plastic Compounders (ABS/PC/Nylon)","query":"engineering plastics","starred":true},{"id":"compounders-compounding-general","label":"Compounding (general)","query":"compounding"}]},{"id":"recyclers","label":"Recyclers","emoji":"♻️","keywords":[{"id":"recyclers-pe-pp-recyclers-reclaimers","label":"PE/PP Recyclers & Reclaimers","query":"plastic recycling","starred":true}]},{"id":"specialty","label":"Specialty","emoji":"⭐","keywords":[{"id":"specialty-masterbatch-buyers-users","label":"Masterbatch Buyers & Users","query":"masterbatch","starred":true},{"id":"specialty-masterbatch-distributors","label":"Masterbatch Distributors","query":"masterbatch"},{"id":"specialty-pipe-manufacturers","label":"Pipe Manufacturers (HDPE/PPR/PVC)","query":"pipe","starred":true},{"id":"specialty-extrusion-any-process","label":"Extrusion (any process)","query":"extrusion"}]}]$json$
from public.companies
on conflict (company_id, key) do nothing;
